// story/plan.mjs — раскадровка «Что, если бы ты мог принять чужой облик?» (второй канал: Артём и Лёха). Запуск: node story/plan.mjs
// [время первого слова фразы, описание кадра, v (что рисовать), доп. поля (in, sfx, amb)]
// Все персонажи одного размера (FIX_S в director.js), камера без зума. Превращение — mo: [t, ключ] у персонажа / лица / зеркала.
import fs from 'node:fs';
const DIR = new URL('.', import.meta.url).pathname;
const words = JSON.parse(fs.readFileSync(DIR + '../timeline/words.json', 'utf8'));
const W = words.words || words;
const DURATION = Math.round((W[W.length - 1].end + 1.2) * 100) / 100;
// время слова: первое слово, начинающееся с w, после t0
const norm = (s) => s.toLowerCase().replace(/[^а-яёa-z0-9-]/g, '');
const A = (w, t0) => { const q = W.find((x) => x.start >= t0 - 0.3 && x.start < t0 + 25 && norm(x.word).startsWith(norm(w))); if (!q) throw new Error(`нет слова «${w}» после ${t0}`); return q.start; };

// ── сокращения
const mk = (k) => (o = {}) => ({ w: k, ...o });
const art = mk('artem'), artt = mk('artemt'), leh = mk('leha'), leht = mk('lehat'), mom = mk('mom'), dad = mk('dad'), ded = mk('ded'), baba = mk('baba'), oldm = mk('oldm'),
  guard = mk('guard'), hunk = mk('hunk'), bossw = mk('bossw'), cash = mk('cash'), bari = mk('bari'), passer = mk('passer'), pass2 = mk('pass2'), pass3 = mk('pass3'), doc = mk('doc'), actor = mk('actor');
// Артём под чужим лицом (уже превращён)
const AL = (o = {}) => artt({ mo: [-5, 'lehat'], ...o });     // Лёха (утро, майка)
const AD = (o = {}) => art({ mo: [-5, 'dad'], ...o });        // папа
const AO = (o = {}) => art({ mo: [-5, 'oldm'], ...o });       // старик с первого этажа
const AH = (o = {}) => art({ mo: [-5, 'hunk'], ...o });       // красавец с плаката
const AB = (o = {}) => art({ mo: [-5, 'bossw'], ...o });      // строгая начальница
const AG = (o = {}) => art({ mo: [-5, 'babas'], ...o });      // бабушка в платке
const FA = (w, o = {}) => ({ w: 'artem', mo: [-5, w], ...o }); // крупный план: Артём под лицом w

const BATH = (o = {}) => ({ set: 'bathroom', so: { mirrorX: 0, ...o } });
const ROOM = (o = {}) => ({ set: 'myroom', so: o });
const STAIRS = (o = {}) => ({ set: 'stairs', so: { doorX: -2400, liftX: -2400, ...o } });
const LHALL = (o = {}) => ({ set: 'hallway', so: o });
const PHALL = (o = {}) => ({ set: 'hallway', so: { mood: 'interiorWarm', ...o } });
const FLAT = (o = {}) => ({ set: 'flat', so: { tv: true, ...o } });
const LKIT = (o = {}) => ({ set: 'kitchen', so: { fridgeX: -560, shelfX: 200, ...o } });
const KIT = (o = {}) => ({ set: 'gkitchen', so: { tea: true, ...o } });
const SHOP = (o = {}) => ({ set: 'shop', so: o });
const CITY = (o = {}) => ({ set: 'city', so: { mood: 'day', ...o } });
const CAFE = { set: 'coffeeshop' };
const CAFE2 = { set: 'cafe' };
const OFF = (o = {}) => ({ set: 'office', so: o });
const YARD = (o = {}) => ({ set: 'courtyard', so: { mood: 'day', ...o } });
const DEDH = (o = {}) => ({ set: 'flat', so: { night: true, sofa: false, ...o } });   // комната деда
const VILL = (o = {}) => ({ set: 'village', so: o });
const WARD = (o = {}) => ({ set: 'ward', so: o });
const GYM = { set: 'gym' };
const CLIN = { set: 'clinic', so: { poster: ['ПАМЯТЬ', 'НЕВРОЛОГ'] } };
const VOID = (light = '#8fb8e8', mood = 'void') => ({ set: 'void', so: { light, mood } });
const ins = (base, k, o = {}) => ({ ...base, ins: { k, ...o } });
const bp = (k, o = {}) => ({ bp: { k, ...o } });
const sfx = (...a) => ({ sfx: a.map(([at, name, gain = -10]) => ({ at, name, gain })) });
const S = (...a) => sfx(...a);
const big = (s, y = 300, at = 0.3) => ({ k: 'big', s, at, y, band: true });
const badge = (s, at = 0.5, until) => ({ k: 'badge', s, at, until });
const thought = (s, at = 0.5) => ({ k: 'thought', s, at, band: true });
const BIG = (s, light = '#ffb070', mood = 'dusk') => ({ ...VOID(light, mood), ui: [big(s, 540, 0.2)] });
// превращение: мерцание + свист
const MO = (...ats) => ats.flatMap((at) => [[Math.max(0, at - 0.32), 'shimmer', -11], [Math.max(0, at - 0.12), 'whoosh', -17]]);
const ARM = (x = -200) => ({ t: 'armchair', x });
const PLAYER = (x = 420, on = false) => ({ t: 'player', x, on });
const RULES = ['ЛЮБОЙ, КОГО ВИДЕЛ ВЖИВУЮ', 'ЛИЦО, РОСТ, ГОЛОС — ВСЁ', 'МЫСЛИ И ПАМЯТЬ — ТВОИ', 'НАЗАД — ПРЕДСТАВЬ СВОЁ ЛИЦО'];
